-- Expanded phone/tablet brand catalog for faster purchase entry.
-- Catalog values are editable later through the existing model-spec workflow.
do $$
declare v_brand_id uuid; v_model_id uuid; v_name text;
begin
  select id into v_brand_id from public.brands where lower(name)=lower('Apple') and (category='phone' or category is null) order by case when category='phone' then 0 else 1 end limit 1;
  if v_brand_id is null then insert into public.brands(name,category,is_active) values ('Apple','phone',true) returning id into v_brand_id; else update public.brands set is_active=true where id=v_brand_id; end if;
  foreach v_name in array array['iPad Pro 13-inch (M5)','iPad Pro 11-inch (M5)','iPad Air 13-inch (M4)','iPad Air 11-inch (M4)','iPad (A16)','iPad mini (A17 Pro)','iPad Pro 13-inch (M4)','iPad Pro 11-inch (M4)','iPad Pro 12.9-inch (6th generation)','iPad Pro 12.9-inch (5th generation)','iPad Pro 12.9-inch (4th generation)','iPad Pro 12.9-inch (3rd generation)','iPad Pro 12.9-inch (2nd generation)','iPad Pro 12.9-inch (1st generation)','iPad Pro 11-inch (4th generation)','iPad Pro 11-inch (3rd generation)','iPad Pro 11-inch (2nd generation)','iPad Pro 11-inch (1st generation)','iPad Pro 10.5-inch','iPad Pro 9.7-inch','iPad Air 13-inch (M3)','iPad Air 11-inch (M3)','iPad Air 13-inch (M2)','iPad Air 11-inch (M2)','iPad Air (5th generation)','iPad Air (4th generation)','iPad Air (3rd generation)','iPad Air 2','iPad Air (1st generation)','iPad (10th generation)','iPad (9th generation)','iPad (8th generation)','iPad (7th generation)','iPad (6th generation)','iPad (5th generation)','iPad mini (6th generation)','iPad mini (5th generation)','iPad mini 4','iPad mini 3','iPad mini 2']::text[] loop
    select id into v_model_id from public.product_models where brand_id=v_brand_id and category='phone' and lower(name)=lower(v_name) limit 1;
    if v_model_id is null then insert into public.product_models(brand_id,category,name,phone_platform,is_active) values (v_brand_id,'phone',v_name,'iphone',true) returning id into v_model_id; else update public.product_models set is_active=true where id=v_model_id; end if;
    insert into public.phone_model_specs(product_model_id,colors,storage_options_gb,imei_count) values (v_model_id,array['Black','White','Blue','Gray']::text[],array[64,128,256,512]::integer[],2) on conflict(product_model_id) do nothing;
  end loop;
  select id into v_brand_id from public.brands where lower(name)=lower('Samsung') and (category='phone' or category is null) order by case when category='phone' then 0 else 1 end limit 1;
  if v_brand_id is null then insert into public.brands(name,category,is_active) values ('Samsung','phone',true) returning id into v_brand_id; else update public.brands set is_active=true where id=v_brand_id; end if;
