  foreach v_name in array array['Xiaomi 15 Ultra','Xiaomi 15 Pro','Xiaomi 15','Xiaomi 14 Ultra','Xiaomi 14 Pro','Xiaomi 14','Xiaomi 13 Ultra','Xiaomi 13 Pro','Xiaomi 13','Xiaomi 12S Ultra','Xiaomi 12 Pro','Xiaomi 12','Xiaomi 11 Ultra','Xiaomi 11T Pro','Xiaomi 11T','Xiaomi 11','Xiaomi Mi 10 Ultra','Xiaomi Mi 10 Pro','Xiaomi Mi 10','Xiaomi MIX Flip','Xiaomi MIX Fold 4','Xiaomi MIX Fold 3','Xiaomi MIX Fold 2','Xiaomi Civi 5 Pro','Xiaomi Civi 4 Pro','Xiaomi Civi 3','Xiaomi 15T Pro','Xiaomi 15T','Xiaomi 14T Pro','Xiaomi 14T','Xiaomi 13T Pro','Xiaomi 13T']::text[] loop
